13	// previewStatuses 提取预览结果状态序列。
14	func previewStatuses(r *PreviewResult) []string {
15		out := make([]string, len(r.Results))
16		for i, x := range r.Results {
17			out[i] = x.Status
18		}
19		return out
20	}
