142	// 即使注入“每次持久化都失败”，预览仍逐项给出业务结果，不出现 storage_error。
143	func TestPreviewIgnoresStorageFailures(t *testing.T) {
144		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
145		l := openOrFail(t, path)
146		SetFailHook(l, &alwaysFailHook{})
147		t.Cleanup(func() { SetFailHook(l, nil) })
148	
149		res, err := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
150			intent("p1", "aa", "usdc", 70),
151			intent("p2", "aa", "usdc", 40),
152		}})
153		if err != nil {
154			t.Fatal(err)
155		}
156		if got, want := previewStatuses(res), []string{StatusSettled, StatusFunds}; strings.Join(got, ",") != strings.Join(want, ",") {
157			t.Fatalf("statuses=%v want %v (preview cannot report storage_error)", got, want)
158		}
159	}
160	
161	type alwaysFailHook struct{}
162	
163	func (alwaysFailHook) FailNextPersist() bool { return true }
