165	// 连续预览相同批次（账本未变）结果一致；随后真实提交按首次提交处理。
166	func TestPreviewDeterministicThenRealSubmit(t *testing.T) {
167		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
168		l := openOrFail(t, path)
169		batch := FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
170			intent("p1", "aa", "usdc", 70),
171			intent("p2", "aa", "usdc", 40),
172		}}
173	
174		r1, err := l.Preview(batch)
175		if err != nil {
176			t.Fatal(err)
177		}
178		r2, err := l.Preview(batch)
179		if err != nil {
180			t.Fatal(err)
181		}
182		j1, _ := json.Marshal(r1)
183		j2, _ := json.Marshal(r2)
184		if !bytes.Equal(j1, j2) {
185			t.Fatalf("repeated previews differ:\n%s\n%s", j1, j2)
186		}
187	
188		// 真实提交仍是首次提交：p1 成功（不是 duplicate），序号从 1 开始。
189		sub, err := l.Submit(batch)
190		if err != nil {
191			t.Fatal(err)
192		}
193		if sub.Results[0].Status != StatusSettled || sub.Results[0].Record.Seq != 1 {
194			t.Fatalf("real submit after preview must be first-time: %+v", sub.Results[0])
195		}
196		if sub.Results[1].Status != StatusFunds {
197			t.Fatalf("real submit second item: %+v", sub.Results[1])
198		}
199		if bal, _ := l.Balance("aa", "usdc"); bal != 30 {
200			t.Fatalf("balance after real submit=%d want 30", bal)
201		}
202	}
