204	// 预览中首次预计成功的编号对本批次后续项生效：相同请求重复（携带预计记录），
205	// 字段不同冲突；两者都不再模拟扣款。
206	func TestPreviewInBatchDuplicateAndConflict(t *testing.T) {
207		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1_000_000}})
208		l := openOrFail(t, path)
209		it := intent("p", "aa", "usdc", 100)
210	
211		res, _ := l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{it, it}})
212		if res.Results[0].Status != StatusSettled || res.Results[1].Status != StatusDuplicate {
213			t.Fatalf("identical repeat: %+v", res.Results)
214		}
215		if d := res.Results[1]; d.Record == nil || d.Record.Seq != 1 || d.Record.Charged != 100 {
216			t.Fatalf("duplicate must carry predicted record: %+v", d)
217		}
218	
219		diff := it
220		diff.Amount = i64p(101) // 独立指针，避免与 it 的 Amount 别名
221		res, _ = l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{it, diff}})
222		if res.Results[0].Status != StatusSettled || res.Results[1].Status != StatusConflict {
223			t.Fatalf("different fields: %+v", res.Results)
224		}
225		if res.Results[1].Record != nil {
226			t.Fatalf("conflict must not carry a record: %+v", res.Results[1])
227		}
228	}
