266	// 已有成功编号仍按原付款字段与费率判断重复/冲突，重复项携带原记录、
267	// 不占余额与本批次额度；原付款已退款也遵守同样规则。
268	func TestPreviewExistingRecordsAndRefunded(t *testing.T) {
269		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1_000_000}})
270		l := openOrFail(t, path)
271		base := intent("p1", "aa", "usdc", 1500)
272		base.Paymaster = "pm-1"
273		base.Nonce = 7
274		if _, err := l.Submit(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{base}}); err != nil {
275			t.Fatal(err)
276		}
277		charged := int64(1504)
278	
279		// 相同请求（含费率）：duplicate，携带原记录（原序号 1，不重新编号）。
280		res, _ := l.Preview(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{base}})
281		d := res.Results[0]
282		if d.Status != StatusDuplicate || d.Record == nil || d.Record.Seq != 1 || d.Record.Charged != charged {
283			t.Fatalf("existing duplicate: %+v", d)
284		}
285		// 字段/费率变化：conflict。
286		for i, mut := range []func(*PaymentIntent, *int){
287			func(it *PaymentIntent, bps *int) { *it.Amount = 1501 },
288			func(it *PaymentIntent, bps *int) { it.Nonce = 8 },
289			func(it *PaymentIntent, bps *int) { *bps = 31 },
290		} {
291			it := base
292			it.Amount = i64p(*base.Amount) // 独立指针，避免突变回写 base
293			bps := 30
294			mut(&it, &bps)
295			r, _ := l.Preview(FeeBatch{FeeBps: bps, Intents: []PaymentIntent{it}})
296			if r.Results[0].Status != StatusConflict {
297				t.Fatalf("mutation %d want conflict, got %+v", i, r.Results[0])
298			}
299		}
300	
301		// 原付款已退款：相同请求仍 duplicate 携带原记录，不再次扣款；
302		// 退回的余额虽可用于新付款，但重复项本身不占余额。
303		if _, err := l.Refund(RefundBatch{Refunds: []RefundRequest{refundReq("r1", "p1", "x")}}); err != nil {
304			t.Fatal(err)
305		}
306		balAfterRefund, _ := l.Balance("aa", "usdc")
307		res, _ = l.Preview(FeeBatch{FeeBps: 30, Intents: []PaymentIntent{base}})
308		if res.Results[0].Status != StatusDuplicate || res.Results[0].Record == nil ||
309			res.Results[0].Record.Seq != 1 {
310			t.Fatalf("refunded original duplicate: %+v", res.Results[0])
311		}
312		if bal, _ := l.Balance("aa", "usdc"); bal != balAfterRefund {
313			t.Fatalf("duplicate after refund changed balance: %d vs %d", bal, balAfterRefund)
314		}
315		// 退款后余额可用于一笔新编号的预计成功，序号接在原记录之后。
316		res, _ = l.Preview(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("new", "aa", "usdc", 100)}})
317		if res.Results[0].Status != StatusSettled || res.Results[0].Record.Seq != 2 {
318			t.Fatalf("new payment after refund: %+v", res.Results[0])
319		}
320	}
